import { BookOpen, Box, CheckCircle2, Download, FileArchive, FileCode2, FileJson, GitCompare, GraduationCap, HardDrive, Layers3, Moon, Play, RotateCcw, Save, Search, Sun, Upload, WandSparkles } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { trpc } from "@/lib/trpc";
import LanguageSelector from "@/components/LanguageSelector";
import catalog from "@/content/commands-catalog.json";
import exampleManifest from "@/content/parametric-examples/manifest.json";
import { resolveCommandInput, shortcutSuggestions, type CommandResolution } from "@/lib/canonical-command-resolver";
import { analyzeNativeGeometry, ARKI_NATIVE_TEMPLATES, getNativeTemplate, type NativeTemplateId } from "@shared/arkiNativeGenerator";
import { approveProposal, proposeFromNaturalLanguage, rejectProposal, simulateProposal, type ParameterProposal } from "@shared/arkiGenerativeAssistant";
import TypologyExecutionPanel from "@/components/TypologyExecutionPanel";
import TypologyDslEditor from "@/components/TypologyDslEditor";

type ShapeKind = "RECTANGULAR_MASS" | "COURTYARD_MASS";
type Geometry = { kind: ShapeKind; width: number; depth: number; height: number; floors: number; courtyardRatio: number };
type ArkSummary = { name: string; projectId: string; geometry: Partial<Geometry>; unknowns: number; sections: string[] };
type CanonicalCommand = { name: string; category: string; syntax: string; arguments: Array<{ name: string; required: boolean; type: string }>; example: string };
type ParametricExample = { exampleId: string; title: string; commandName: string; category: string; command: string; mode: string; expectedOutcome: string; learningObjective: string; path: string; artifacts: string[] };
const CANONICAL_RUNTIME_COMMANDS = ["/PROJECT OPEN", "/PROJECT SET SCOPE", "/OBJECTIVE SET", "/CONSTRAINT SET", "/EVIDENCE ADD", "/HUMAN REVIEW", "/INTERPRET REVIEW", "/ALTERNATIVE PROMOTE", "/MULTIOBJECTIVE", "/DECISION RECORD"];
const runtimeCommands = (catalog as CanonicalCommand[]).filter((command) => CANONICAL_RUNTIME_COMMANDS.includes(command.name));
const parametricExamples = (exampleManifest as { examples: ParametricExample[] }).examples;
const PARAMETER_CATALOG = [
  { key: "width", label: "Ancho", description: "Dimensión longitudinal de la masa", unit: "m" },
  { key: "depth", label: "Fondo", description: "Profundidad de la masa", unit: "m" },
  { key: "height", label: "Altura por nivel", description: "Altura conceptual entre pisos", unit: "m" },
  { key: "floors", label: "Niveles", description: "Número de niveles conceptuales", unit: "niveles" },
  { key: "courtyardRatio", label: "Proporción de patio", description: "Vacío interior para masa con patio", unit: "%" },
  { key: "kind", label: "Tipo de geometría", description: "Masa compacta o masa con patio", unit: "tipo" },
] as const;
type TutorialStep = { title: string; detail: string; action: string };
const tutorial: TutorialStep[] = [
  { title: "Reconoce la geometría", detail: "Una propuesta paramétrica comienza como una hipótesis volumétrica, no como una decisión final.", action: "Observa el volumen en planta, alzado y axonometría." },
  { title: "Muta un parámetro", detail: "Modifica ancho, fondo, altura o número de niveles y comprueba cómo cambia el volumen.", action: "Cambia el ancho con el slider y vuelve a observar." },
  { title: "Lee las consecuencias", detail: "ARKI conserva la geometría y señala lo que todavía necesita evidencia arquitectónica.", action: "Revisa los UNKNOWN antes de exportar." },
  { title: "Exporta y vuelve a leer", detail: "El archivo .ark conserva la propuesta, el grafo, provenance y límites para que ARKI pueda asimilarla después.", action: "Exporta el paquete y luego importa el .ark." },
];
const quiz = { question: "¿Qué representa un archivo .ark en ARKI?", options: ["Una decisión constructiva aprobada", "Una propuesta geométrica trazable que requiere revisión humana", "Un archivo nativo .rvt generado sin Revit", "Un render fotorrealista certificado"], answer: 1 };

function initialGeometry(): Geometry { return { kind: "RECTANGULAR_MASS", width: 24, depth: 16, height: 3.2, floors: 2, courtyardRatio: 0.25 }; }
function stableId() { return typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `arki-${Date.now()}`; }
function graphFor(geometry: Geometry) { return { contractVersion: "ARKI-PARAMETRIC-1.0" as const, graphId: `mass-${geometry.kind.toLowerCase()}`, nodes: [{ id: "width", op: "constant" as const, params: { value: geometry.width } }, { id: "depth", op: "constant" as const, params: { value: geometry.depth } }, { id: "height", op: "constant" as const, params: { value: geometry.height * geometry.floors } }, { id: "mass", op: "rectangle_points" as const, params: { width: geometry.width, height: geometry.depth } }], outputs: ["mass"], units: "m", tolerance: 0.001, humanReviewRequired: true as const }; }
function download(name: string, content: string, type: string) { const url = URL.createObjectURL(new Blob([content], { type })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = name; anchor.click(); URL.revokeObjectURL(url); }
function number(value: string, fallback: number) { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : fallback; }

function GeometryPreview({ geometry, animating = false }: { geometry: Geometry; animating?: boolean }) {
  const scale = Math.min(290 / geometry.width, 180 / geometry.depth);
  const w = geometry.width * scale;
  const d = geometry.depth * scale;
  const x = 180 - w / 2;
  const y = 185 - d / 2;
  const h = Math.min(140, geometry.height * geometry.floors * 18);
  const court = geometry.kind === "COURTYARD_MASS" ? Math.min(w, d) * geometry.courtyardRatio * 0.6 : 0;
  return <div className={`relative grid gap-4 transition-all duration-300 lg:grid-cols-3 ${animating ? "scale-[0.995] opacity-70" : "scale-100 opacity-100"}`}><div className="rounded-xl border border-[#294765] bg-[#071a30] p-3"><p className="mb-2 text-[10px] uppercase tracking-[0.16em] text-[#7893af]">Axonometría conceptual</p><svg viewBox="0 0 360 260" className="h-[260px] w-full" role="img" aria-label="Vista axonométrica paramétrica"><defs><linearGradient id="arkiMass" x1="0" x2="1"><stop offset="0" stopColor="#6ea8ff" stopOpacity=".8" /><stop offset="1" stopColor="#f0a35b" stopOpacity=".75" /></linearGradient></defs><polygon points={`${x},${y} ${x + w},${y} ${x + w + 24},${y - 18} ${x + 24},${y - 18}`} fill="#8bbaff" fillOpacity=".55" stroke="#b8d5ff" /><polygon points={`${x + w},${y} ${x + w + 24},${y - 18} ${x + w + 24},${y - 18 + h} ${x + w},${y + h}`} fill="#f0a35b" fillOpacity=".45" stroke="#f6c995" /><polygon points={`${x},${y} ${x + w},${y} ${x + w},${y + h} ${x},${y + h}`} fill="url(#arkiMass)" fillOpacity=".5" stroke="#edf4ff" /><line x1={x} y1={y + h / 2} x2={x + w} y2={y + h / 2} stroke="#edf4ff" strokeOpacity=".45" strokeDasharray="4 4" />{Array.from({ length: Math.max(0, geometry.floors - 1) }).map((_, i) => <line key={i} x1={x} y1={y + ((i + 1) * h) / geometry.floors} x2={x + w} y2={y + ((i + 1) * h) / geometry.floors} stroke="#edf4ff" strokeOpacity=".25" />)}<text x="16" y="238" fill="#7893af" fontSize="10">{geometry.width.toFixed(1)} m × {geometry.depth.toFixed(1)} m × {(geometry.height * geometry.floors).toFixed(1)} m</text></svg></div><div className="rounded-xl border border-[#294765] bg-[#071a30] p-3"><p className="mb-2 text-[10px] uppercase tracking-[0.16em] text-[#7893af]">Planta paramétrica</p><svg viewBox="0 0 360 260" className="h-[260px] w-full" role="img" aria-label="Planta paramétrica"><rect x={x} y={y + 8} width={w} height={d} rx="2" fill="#14385b" stroke="#8bbaff" strokeWidth="2" />{court > 0 && <><rect x={x + (w - court) / 2} y={y + 8 + (d - court) / 2} width={court} height={court} fill="#173d39" stroke="#65dfb3" strokeDasharray="4 3" /><text x={x + (w - court) / 2 + 4} y={y + 8 + (d - court) / 2 + court / 2} fill="#a7f3d0" fontSize="9">patio</text></>}<line x1={x} y1={y + 8 + d / 2} x2={x + w} y2={y + 8 + d / 2} stroke="#f0a35b" strokeDasharray="5 4" /><text x="16" y="238" fill="#7893af" fontSize="10">{geometry.kind === "COURTYARD_MASS" ? "Masa con vacío interior" : "Masa compacta"}</text></svg></div><div className="rounded-xl border border-[#294765] bg-[#071a30] p-3"><p className="mb-2 text-[10px] uppercase tracking-[0.16em] text-[#7893af]">Lectura de control</p><div className="space-y-3 pt-3 text-xs text-[#b8cbe0]"><div className="flex justify-between"><span>Superficie por nivel</span><strong className="text-[#edf4ff]">{(geometry.width * geometry.depth).toFixed(1)} m²</strong></div><div className="flex justify-between"><span>Área construida conceptual</span><strong className="text-[#edf4ff]">{(geometry.width * geometry.depth * geometry.floors * (1 - (geometry.kind === "COURTYARD_MASS" ? geometry.courtyardRatio * 0.35 : 0))).toFixed(1)} m²</strong></div><div className="flex justify-between"><span>Niveles</span><strong className="text-[#edf4ff]">{geometry.floors}</strong></div><Separator className="bg-[#294765]" /><p className="leading-5 text-[#f6c995]">Esto es una hipótesis volumétrica. ARKI debe comprobar programa, circulación, estructura, regulación, costo, iluminación y ventilación.</p></div></div>{animating && <div className="pointer-events-none absolute inset-0 flex items-center justify-center"><div className="rounded-full border border-[#f0a35b]/40 bg-[#071a30]/90 px-4 py-2 text-xs text-[#f6c995]">Actualizando geometría…</div></div>}</div>;
}

export default function ArkiParametricRuntimePage() {
  const [projectId, setProjectId] = useState(() => localStorage.getItem("arki-active-project-id") || "UPAO-001");
  const [proposalName, setProposalName] = useState("casa_yvan");
  const [geometry, setGeometry] = useState<Geometry>(initialGeometry);
  const [comparisonGeometry, setComparisonGeometry] = useState<Geometry>(() => ({ ...initialGeometry(), width: 30, kind: "COURTYARD_MASS" }));
  const [compareMode, setCompareMode] = useState(false);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem("arki-parametric-theme") !== "light");
  const [geometryAnimating, setGeometryAnimating] = useState(false);
  const [arkDragging, setArkDragging] = useState(false);
  const [arkSummary, setArkSummary] = useState<ArkSummary | null>(null);
  const [selectedRuntimeCommand, setSelectedRuntimeCommand] = useState(CANONICAL_RUNTIME_COMMANDS[0]);
  const [selectedTemplateId, setSelectedTemplateId] = useState<NativeTemplateId | null>(null);
  const [selectedTypologyId, setSelectedTypologyId] = useState("");
  const [assistantText, setAssistantText] = useState("");
  const [assistantProposal, setAssistantProposal] = useState<ParameterProposal | null>(null);
  const [commandInput, setCommandInput] = useState("");
  const [commandResolution, setCommandResolution] = useState<CommandResolution | null>(null);
  const [runtimeMode, setRuntimeMode] = useState<"EXPLORE" | "APPLY" | "DECIDE">("EXPLORE");
  const [showAllCommands, setShowAllCommands] = useState(false);
  const [parameterSearch, setParameterSearch] = useState("");
  const [tutorialStep, setTutorialStep] = useState(0);
  const [quizAnswer, setQuizAnswer] = useState<number | null>(null);
  const [quizScore, setQuizScore] = useState<number | null>(null);
  const [sessionId, setSessionId] = useState(() => `${projectId}-${stableId()}`.slice(0, 128));
  const [restored, setRestored] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const commandInputRef = useRef<HTMLInputElement>(null);
  const animationTimer = useRef<number | null>(null);
  const utils = trpc.useUtils();
  const sessions = trpc.parametricRuntime.sessions.list.useQuery({ projectId }, { enabled: projectId.trim().length >= 3 });
  const saveSession = trpc.parametricRuntime.sessions.save.useMutation({ onSuccess: () => { setRestored(true); void utils.parametricRuntime.sessions.list.invalidate({ projectId }); } });
  const exportPackage = trpc.parametricRuntime.exportPackage.useMutation();
  const assimilateArk = trpc.parametricRuntime.assimilateArk.useMutation();
  const hostWorkers = trpc.parametricRuntime.hostWorkers.catalog.useQuery();
  const typologyCatalog = trpc.parametricRuntime.typologies.useQuery();
  const normativeValidation = trpc.parametricRuntime.validateNormative.useMutation();
  const activeRuntimeCommand = runtimeCommands.find((command) => command.name === selectedRuntimeCommand) ?? runtimeCommands[0];
  const visibleRuntimeCommands = showAllCommands ? (catalog as CanonicalCommand[]) : runtimeCommands;
  const graph = useMemo(() => graphFor(geometry), [geometry]);
  const previewResult = useMemo(() => ({ status: "PREVIEW_READY", geometry, graph, projectId, humanReviewRequired: true, unknowns: ["program", "circulation", "structure", "regulation", "cost"], source: "ARKI-PARAMETRIC-RUNTIME", canonicalCommand: activeRuntimeCommand?.name, commandSyntax: activeRuntimeCommand?.syntax, commandContext: { projectId, artifact: arkSummary?.name ?? `${proposalName}.ark`, geometryKind: geometry.kind, provenance: "User interaction / ARKI-PARAMETRIC-RUNTIME" } }), [activeRuntimeCommand, arkSummary?.name, geometry, graph, projectId, proposalName]);
  const nativeAnalysis = useMemo(() => analyzeNativeGeometry(geometry, selectedTemplateId), [geometry, selectedTemplateId]);
  const assistantSimulation = useMemo(() => assistantProposal ? simulateProposal(geometry, assistantProposal) : null, [assistantProposal, geometry]);

  const visibleParameters = useMemo(() => PARAMETER_CATALOG.filter((parameter) => `${parameter.label} ${parameter.key} ${parameter.description} ${parameter.unit}`.toLocaleLowerCase().includes(parameterSearch.toLocaleLowerCase().trim())), [parameterSearch]);
  useEffect(() => { localStorage.setItem("arki-active-project-id", projectId); }, [projectId]);
  useEffect(() => { const handleShortcut = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "y") { event.preventDefault(); commandInputRef.current?.focus(); commandInputRef.current?.select(); } }; window.addEventListener("keydown", handleShortcut); return () => window.removeEventListener("keydown", handleShortcut); }, []);
  useEffect(() => { localStorage.setItem("arki-parametric-theme", darkMode ? "dark" : "light"); }, [darkMode]);
  useEffect(() => { setSessionId((current) => current.startsWith(`${projectId}-`) ? current : `${projectId}-${stableId()}`.slice(0, 128)); setRestored(false); }, [projectId]);
  useEffect(() => {
    if (restored || !sessions.data?.length) return;
    const current = sessions.data.find((item) => item.sessionId === sessionId) ?? sessions.data[0];
    if (!current) return;
    try { const parsed = JSON.parse(current.parameters) as Partial<Geometry> & { proposalName?: string }; setGeometry((value) => ({ ...value, ...parsed })); if (parsed.proposalName) setProposalName(parsed.proposalName); setTutorialStep(current.tutorialStep); setQuizScore(current.exerciseScore); setRestored(true); } catch { setRestored(true); }
  }, [restored, sessions.data, sessionId]);
  useEffect(() => {
    if (!restored || projectId.trim().length < 3) return;
    const timer = window.setTimeout(() => saveSession.mutate({ projectId, sessionId, commandName: "ARKI-PARAMETRIC-RUNTIME", parameters: { ...geometry, proposalName }, previewResult, tutorialStep, exerciseScore: quizScore, exerciseState: quizScore === 100 ? "PASSED" : "IN_PROGRESS", lastAction: "AUTOSAVE" }), 700);
    return () => window.clearTimeout(timer);
  }, [geometry, projectId, proposalName, previewResult, quizScore, restored, saveSession, sessionId, tutorialStep]);

  function pulseGeometry() { setGeometryAnimating(true); if (animationTimer.current) window.clearTimeout(animationTimer.current); animationTimer.current = window.setTimeout(() => setGeometryAnimating(false), 360); }
  function setNumber(key: keyof Geometry, value: string) { pulseGeometry(); setGeometry((current) => ({ ...current, [key]: number(value, current[key] as number) })); }
  function setComparisonNumber(key: keyof Geometry, value: string) { setComparisonGeometry((current) => ({ ...current, [key]: number(value, current[key] as number) })); }
  function askNativeAssistant() {
    const text = assistantText.trim();
    if (!text) return;
    setAssistantProposal(proposeFromNaturalLanguage(text, geometry));
    toast.success("Propuesta creada; todavía no modifica el proyecto activo.");
  }

  function acceptAssistantProposal() {
    if (!assistantProposal || assistantProposal.status === "REJECTED") return;
    const accepted = approveProposal(assistantProposal);
    setAssistantProposal(accepted);
    if (accepted.templateId) applyNativeTemplate(accepted.templateId);
    else setGeometry((current) => ({ ...current, ...accepted.params }));
    toast.success("Propuesta aceptada explícitamente; revisa la geometría resultante antes de guardar.");
  }

  function rejectAssistantProposal() {
    if (!assistantProposal) return;
    setAssistantProposal(rejectProposal(assistantProposal));
    toast.info("Propuesta rechazada; no se modificó el proyecto.");
  }

  function applyNativeTemplate(templateId: NativeTemplateId) {
    const template = getNativeTemplate(templateId);
    if (!template) return;
    setSelectedTemplateId(templateId);
    setProposalName(template.id.toLowerCase());
    setGeometry({ ...template.geometry });
    setTutorialStep(Math.max(tutorialStep, 1));
    toast.success(`Plantilla cargada: ${template.name}`);
  }

  function previewCommand(input = commandInput) { const resolution = resolveCommandInput(input, "es"); setCommandResolution(resolution); if (resolution.resolvedCanonical) { const canonicalName = resolution.resolvedCanonical.split(/\s+/).slice(0, 3).join(" "); if (runtimeCommands.some((command) => command.name === canonicalName)) setSelectedRuntimeCommand(canonicalName); } }
  async function exportAll() { const result = await exportPackage.mutateAsync({ projectId, name: proposalName, geometry, graph }); result.files.forEach((file) => download(file.fileName, file.content, file.format === "ARK" ? "application/json" : file.format === "GHX" ? "application/xml" : "application/json")); setTutorialStep(Math.max(tutorialStep, 3)); toast.success("Paquete ARKI exportado: .ark + .dyn + .ghx"); }
  function submitQuiz() { if (quizAnswer === null) return; const score = quizAnswer === quiz.answer ? 100 : 0; setQuizScore(score); setTutorialStep(Math.max(tutorialStep, 2)); toast[score ? "success" : "error"](score ? "Ejercicio aprobado" : "Revisa el concepto y vuelve a intentarlo"); }
  function readArk(file: File) { const reader = new FileReader(); reader.onload = () => { const raw = String(reader.result); try { const parsed = JSON.parse(raw) as { name?: string; projectId?: string; geometry?: Partial<Geometry>; unknowns?: unknown[]; [key: string]: unknown }; setArkSummary({ name: String(parsed.name ?? file.name), projectId: String(parsed.projectId ?? projectId), geometry: parsed.geometry ?? {}, unknowns: Array.isArray(parsed.unknowns) ? parsed.unknowns.length : 0, sections: ["manifest", "project", "geometry", "semantics", "provenance", "alternatives", "evaluations", "unknowns", "history"] }); } catch { setArkSummary(null); } assimilateArk.mutate({ projectId, content: raw }, { onSuccess: (result) => { if ("status" in result && result.status === "REJECTED") toast.error(result.reason); else toast.success(`ARKI interpretó la propuesta como ${result.architecturalRole}`); }, onError: (error) => toast.error(error.message) }); }; reader.readAsText(file); }
  function acceptArk(file: File | undefined) { if (!file) return; if (!file.name.toLowerCase().endsWith(".ark")) { toast.error("Solo se pueden importar archivos .ark"); return; } readArk(file); }
  function validateNormative() {
    const typology = selectedTemplateId === "TROPICAL_STADIUM" ? "Estadio" : selectedTemplateId === "HOSPITAL_COMPLEX" ? "Hospital" : selectedTemplateId === "INTERPROVINCIAL_TERMINAL" ? "Terminal" : "Vivienda";
    const facts = [
      { variable: "altura_libre_estadio_m", value: geometry.height * geometry.floors, unit: "m", source: "ARKI-PARAMETRIC-RUNTIME" },
      { variable: "tiempo_evacuacion_min", value: 15, unit: "min", source: "valor de prueba; reemplazar por simulación" },
      { variable: "ancho_rampa_m", value: 1.2, unit: "m", source: "hipótesis paramétrica" },
      { variable: "pendiente_rampa_pct", value: 8, unit: "%", source: "hipótesis paramétrica" },
      { variable: "altura_libre_vivienda_m", value: geometry.height, unit: "m", source: "geometría conceptual" },
      { variable: "area_vivienda_m2", value: geometry.width * geometry.depth, unit: "m²", source: "geometría conceptual" },
    ];
    normativeValidation.mutate({ projectId, typology, facts }, { onSuccess: (result) => toast.success(`Validación RNE: ${result.validation.pass} PASS · ${result.validation.fail} FAIL · ${result.validation.unknown} UNKNOWN`), onError: (error) => toast.error(error.message) });
  }

  function reset() { setGeometry(initialGeometry()); setProposalName("casa_yvan"); setTutorialStep(0); setQuizAnswer(null); setQuizScore(null); setRestored(true); toast.info("Sesión reiniciada localmente; se guardará por proyecto"); }

  return <main className={`min-h-[calc(100vh-4rem)] px-4 py-6 text-[#edf4ff] transition-colors duration-300 sm:px-6 lg:px-8 ${darkMode ? "bg-[#071a30]" : "bg-[#dce8f5]"}`}>
      <div className="mb-6"><TypologyExecutionPanel /></div><div className="mx-auto max-w-[1600px] space-y-5"><header className="flex flex-col gap-4 border-b border-[#294765] pb-5 lg:flex-row lg:items-end lg:justify-between"><div><div className="mb-2 flex items-center gap-2 text-xs uppercase tracking-[0.22em] text-[#f0a35b]"><Box className="h-4 w-4" /> ARKI-PARAMETRIC-RUNTIME</div><h1 className={`font-serif text-3xl sm:text-4xl ${darkMode ? "text-[#edf4ff]" : "text-[#102947]"}`}>Geometría paramétrica + aprendizaje</h1><p className={`mt-2 max-w-4xl text-sm leading-6 ${darkMode ? "text-[#b8cbe0]" : "text-[#294765]"}`}>Construye una hipótesis volumétrica, observa sus cambios en tiempo real, expórtala a Dynamo/Revit y Rhino/Grasshopper mediante formatos intercambiables, y conserva una propuesta `.ark` que ARKI pueda volver a leer con provenance y UNKNOWNs.</p></div><div className="flex flex-wrap items-center gap-2"><LanguageSelector /> <Badge className="border border-emerald-400/30 bg-emerald-400/10 text-emerald-200"><HardDrive className="mr-1.5 h-3.5 w-3.5" />{saveSession.isPending ? "Guardando…" : "Sesión persistente"}</Badge><Button variant="outline" className="border-[#557da5] text-[#d7e5f4]" onClick={() => setDarkMode((value) => !value)}>{darkMode ? <Sun className="mr-2 h-4 w-4" /> : <Moon className="mr-2 h-4 w-4" />}{darkMode ? "Modo claro" : "Modo oscuro"}</Button><Button variant="outline" className="border-[#557da5] text-[#d7e5f4]" onClick={reset}><RotateCcw className="mr-2 h-4 w-4" />Reiniciar</Button></div></header>
    <Card className="border-[#294765] bg-[#0d223d]">
      <CardContent className="space-y-4 p-4">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <div className="flex items-center gap-2 text-sm font-medium"><WandSparkles className="h-4 w-4 text-[#f0a35b]" />Generador nativo ARKI</div>
            <p className="mt-1 max-w-3xl text-[11px] leading-5 text-[#9eb6ce]">Selecciona una plantilla segura de primera parte. ARKI genera una hipótesis paramétrica, calcula métricas conceptuales y alerta sobre revisiones necesarias; no ejecuta código de terceros.</p>
          </div>
          <Badge className="border border-emerald-400/30 bg-emerald-400/10 text-emerald-200">ARKI-NATIVE-GENERATOR-1.0 · revisión humana</Badge>
        </div>
        <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-5">
          {ARKI_NATIVE_TEMPLATES.map((template) => <button key={template.id} type="button" onClick={() => applyNativeTemplate(template.id)} className={selectedTemplateId === template.id ? "rounded-lg border border-[#f0a35b] bg-[#49351f] p-3 text-left" : "rounded-lg border border-[#294765] bg-[#081a30] p-3 text-left transition-colors hover:border-[#f0a35b]"}><span className="block text-xs font-medium text-[#edf4ff]">{template.name}</span><span className="mt-1 block text-[10px] leading-4 text-[#9eb6ce]">{template.description}</span><span className="mt-2 block font-mono text-[9px] text-[#f6c995]">{template.geometry.width} × {template.geometry.depth} m · {template.geometry.floors} niveles</span></button>)}
        </div>
        <div className="rounded-lg border border-[#557da5] bg-[#081a30] p-3">
          <div className="flex flex-wrap items-center justify-between gap-2"><div><strong className="block text-xs text-[#edf4ff]">Biblioteca declarativa de tipologías</strong><span className="text-[10px] text-[#9eb6ce]">Cada ficha declara parámetros, dominios normativos, métricas y evidencia requerida. Son plantillas de referencia, no expedientes aprobados.</span></div><Badge className="border border-[#f0a35b]/30 bg-[#f0a35b]/10 text-[#f6c995]">{typologyCatalog.data?.total ?? "…"} tipologías</Badge></div>
          <div className="mt-3 flex flex-col gap-2 sm:flex-row"><select value={selectedTypologyId} onChange={(event) => setSelectedTypologyId(event.target.value)} className="h-9 flex-1 rounded-md border border-[#557da5] bg-[#0d223d] px-3 text-xs text-[#edf4ff]"><option value="">Seleccionar tipología para inspeccionar…</option>{typologyCatalog.data?.typologies.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.category}</option>)}</select><span className="self-center text-[10px] text-[#7893af]">Estado: REFERENCE_TEMPLATE · revisión humana requerida</span></div>
          {selectedTypologyId && (() => { const item = typologyCatalog.data?.typologies.find((candidate) => candidate.id === selectedTypologyId); return item ? <div className="mt-3 grid gap-2 lg:grid-cols-[1.3fr_1fr_1fr]"><div><strong className="text-xs text-[#edf4ff]">{item.name}</strong><p className="mt-1 text-[10px] leading-4 text-[#b8cbe0]">{item.description}</p><p className="mt-1 text-[10px] text-[#7893af]">Escala: {item.scale} · Categoría: {item.category}</p></div><div><span className="block text-[10px] text-[#7893af]">Dominios normativos</span><p className="mt-1 text-[10px] text-[#f6c995]">{item.ruleDomains.join(" · ")}</p></div><div><span className="block text-[10px] text-[#7893af]">Métricas / evidencia</span><p className="mt-1 text-[10px] text-[#b8d5ff]">{item.metrics.join(" · ")}</p><p className="mt-1 text-[10px] text-[#9eb6ce]">{item.evidenceRequired.join(" · ")}</p></div></div> : null; })()}
        </div>
        <div className="grid gap-2 sm:grid-cols-4">
          {[['Área por nivel', `${nativeAnalysis.metrics.floorArea} m²`], ['Área construida conceptual', `${nativeAnalysis.metrics.conceptualBuiltArea} m²`], ['Altura total', `${nativeAnalysis.metrics.totalHeight} m`], ['Patio', `${nativeAnalysis.metrics.courtyardArea} m²`]].map(([label, value]) => <div key={label} className="rounded-lg border border-[#294765] bg-[#081a30] p-3"><span className="block text-[10px] text-[#7893af]">{label}</span><strong className="mt-1 block text-sm text-[#edf4ff]">{value}</strong></div>)}
        </div>
        <div className="flex flex-wrap gap-2">{nativeAnalysis.alerts.map((alert) => <span key={alert.code} className={alert.severity === "WARNING" ? "rounded-full border border-amber-400/30 bg-amber-400/10 px-2.5 py-1 text-[10px] text-amber-100" : "rounded-full border border-sky-400/30 bg-sky-400/10 px-2.5 py-1 text-[10px] text-sky-100"}>{alert.code}: {alert.message}</span>)}</div>
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-[#557da5] bg-[#081a30] p-3"><div><strong className="block text-xs text-[#edf4ff]">Validación normativa RNE Perú</strong><span className="text-[10px] text-[#9eb6ce]">Referencia trazable; sin promoción al Core y con revisión profesional obligatoria.</span></div><Button type="button" size="sm" onClick={validateNormative} disabled={normativeValidation.isPending} className="bg-[#6ea8ff] text-[#071a30]">{normativeValidation.isPending ? "Validando…" : "Validar hechos del proyecto"}</Button></div>
        {normativeValidation.data && <div className="grid gap-2 sm:grid-cols-4">{[["PASS", normativeValidation.data.validation.pass, "text-emerald-200"], ["FAIL", normativeValidation.data.validation.fail, "text-rose-200"], ["UNKNOWN", normativeValidation.data.validation.unknown, "text-amber-200"], ["Reglas", normativeValidation.data.validation.ruleCount, "text-[#edf4ff]"]].map(([label, value, color]) => <div key={String(label)} className="rounded-lg border border-[#294765] bg-[#081a30] p-2"><span className="block text-[10px] text-[#7893af]">{label}</span><strong className={`text-lg ${color}`}>{value}</strong></div>)}</div>}
      </CardContent>
    </Card>
    <Card className="border-[#294765] bg-[#0d223d]">
      <CardContent className="space-y-3 p-4">
        <div className="flex flex-wrap items-center justify-between gap-2"><div><div className="flex items-center gap-2 text-sm font-medium"><WandSparkles className="h-4 w-4 text-[#f0a35b]" />Asistente ARKI · lenguaje natural</div><p className="mt-1 text-[11px] text-[#9eb6ce]">Describe un encargo. ARKI sólo crea una propuesta trazable; simula antes/después y espera tu aprobación.</p></div><Badge className="border border-amber-400/30 bg-amber-400/10 text-amber-100">AI_PROPOSED ≠ APROBADO</Badge></div>
        <div className="flex flex-col gap-2 sm:flex-row"><Input value={assistantText} onChange={(event) => setAssistantText(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") askNativeAssistant(); }} placeholder="Ej.: Diseña un estadio para 80000 personas en Iquitos" className="border-[#294765] bg-[#081a30] text-[#edf4ff]" /><Button type="button" onClick={askNativeAssistant} className="bg-[#f0a35b] text-[#081a30] hover:bg-[#f6c995]"><WandSparkles className="mr-2 h-4 w-4" />Proponer</Button></div>
        {assistantProposal && <div className="rounded-lg border border-[#294765] bg-[#081a30] p-3 text-xs"><div className="flex flex-wrap items-center justify-between gap-2"><strong className="text-[#edf4ff]">{assistantProposal.id} · {assistantProposal.status}</strong><span className="text-[#f6c995]">Riesgo: {assistantProposal.risk}</span></div><p className="mt-2 text-[#b8cbe0]">{assistantProposal.reason}</p><p className="mt-1 text-[10px] text-[#7893af]">Proveedor: {assistantProposal.provider} · {assistantProposal.humanReviewRequired ? "Revisión humana obligatoria" : ""}</p>{assistantSimulation && <div className="mt-3 grid gap-2 sm:grid-cols-3"><div><span className="text-[10px] text-[#7893af]">Campos modificados</span><strong className="block text-[#edf4ff]">{assistantSimulation.changedFields.length}</strong></div><div><span className="text-[10px] text-[#7893af]">Área antes</span><strong className="block text-[#edf4ff]">{assistantSimulation.before.metrics.floorArea} m²</strong></div><div><span className="text-[10px] text-[#7893af]">Área después</span><strong className="block text-[#edf4ff]">{assistantSimulation.after.metrics.floorArea} m²</strong></div></div>}<div className="mt-3 flex flex-wrap gap-2"><Button type="button" size="sm" onClick={acceptAssistantProposal} disabled={assistantProposal.status === "ACCEPTED" || assistantProposal.status === "REJECTED"}>Aprobar y aplicar</Button><Button type="button" size="sm" variant="outline" onClick={rejectAssistantProposal} disabled={assistantProposal.status === "REJECTED"}>Rechazar</Button></div></div>}
      </CardContent>
    </Card>
    <TypologyDslEditor />
    <section className="grid gap-4 lg:grid-cols-[1fr_1fr_1fr]"><Card className="border-[#294765] bg-[#0d223d]"><CardContent className="space-y-3 p-4"><div className="flex items-center gap-2 text-sm font-medium"><Layers3 className="h-4 w-4 text-[#f0a35b]" />Proyecto y propuesta</div><Input value={projectId} onChange={(event) => setProjectId(event.target.value.toUpperCase())} className="border-[#557da5] bg-[#081a30] font-mono text-xs text-[#edf4ff]" placeholder="ID del proyecto" /><Input value={proposalName} onChange={(event) => setProposalName(event.target.value)} className="border-[#557da5] bg-[#081a30] text-xs text-[#edf4ff]" placeholder="casa_yvan" /><div className="flex gap-2"><Button size="sm" onClick={() => saveSession.mutate({ projectId, sessionId, commandName: "ARKI-PARAMETRIC-RUNTIME", parameters: { ...geometry, proposalName }, previewResult, tutorialStep, exerciseScore: quizScore, exerciseState: quizScore === 100 ? "PASSED" : "IN_PROGRESS", lastAction: "MANUAL_SAVE" })} className="bg-[#6ea8ff] text-[#071a30]"><Save className="mr-1.5 h-3.5 w-3.5" />Guardar ahora</Button><span className="self-center text-[10px] text-[#7893af]">{sessions.data?.length ?? 0} sesiones recuperables</span></div></CardContent></Card><Card className="border-[#294765] bg-[#0d223d]"><CardContent className="space-y-3 p-4"><div className="flex items-center gap-2 text-sm font-medium"><WandSparkles className="h-4 w-4 text-[#f0a35b]" />Tipo de geometría</div><div className="flex gap-2">{(["RECTANGULAR_MASS", "COURTYARD_MASS"] as ShapeKind[]).map((kind) => <button key={kind} type="button" onClick={() => setGeometry((current) => ({ ...current, kind }))} className={geometry.kind === kind ? "flex-1 rounded border border-[#f0a35b] bg-[#49351f] px-2 py-2 text-xs text-[#f6c995]" : "flex-1 rounded border border-[#557da5] bg-[#081a30] px-2 py-2 text-xs text-[#9eb6ce]"}>{kind === "RECTANGULAR_MASS" ? "Masa compacta" : "Masa + patio"}</button>)}</div><p className="text-[11px] leading-5 text-[#7893af]">La forma es editable; la función arquitectónica todavía necesita un encargo, programa, normativa y revisión.</p></CardContent></Card><Card className="border-[#294765] bg-[#0d223d]"><CardContent className="space-y-3 p-4"><div className="flex items-center gap-2 text-sm font-medium"><FileArchive className="h-4 w-4 text-[#f0a35b]" />Leer una propuesta .ark</div><p className="text-[11px] leading-5 text-[#9eb6ce]">Importa una propuesta sin convertirla automáticamente en una decisión.</p><input ref={fileRef} type="file" accept=".ark,application/json" className="hidden" onChange={(event) => { acceptArk(event.target.files?.[0]); event.currentTarget.value = ""; }} /><button type="button" onClick={() => fileRef.current?.click()} onDragOver={(event) => { event.preventDefault(); setArkDragging(true); }} onDragLeave={() => setArkDragging(false)} onDrop={(event) => { event.preventDefault(); setArkDragging(false); acceptArk(event.dataTransfer.files?.[0]); }} className={arkDragging ? "w-full scale-[1.02] rounded-xl border border-dashed border-[#f0a35b] bg-[#49351f] p-5 text-center transition-all duration-200" : "w-full rounded-xl border border-dashed border-[#557da5] bg-[#081a30] p-5 text-center transition-all duration-200 hover:border-[#f0a35b]"}><Upload className="mx-auto mb-2 h-7 w-7 text-[#f0a35b]" /><span className="block text-sm font-medium">Arrastra aquí tu archivo .ark</span><span className="mt-1 block text-[11px] text-[#9eb6ce]">o haz clic para buscarlo</span></button>{arkSummary && <div className="rounded-lg border border-emerald-400/30 bg-emerald-400/10 p-3 text-[11px] text-[#b8cbe0]"><div className="flex items-center gap-2 text-emerald-200"><CheckCircle2 className="h-4 w-4" />Resumen cargado: {arkSummary.name}</div><p className="mt-2">Proyecto: <span className="font-mono">{arkSummary.projectId}</span> · UNKNOWNs: {arkSummary.unknowns}</p><p className="mt-1 text-[#9eb6ce]">Geometría: {arkSummary.geometry.kind ?? "no declarada"} · {arkSummary.geometry.width ?? "—"} × {arkSummary.geometry.depth ?? "—"} m · {arkSummary.geometry.floors ?? "—"} niveles</p><p className="mt-1 text-[#7893af]">Secciones: {arkSummary.sections.join(" · ")}</p></div>}</CardContent></Card></section><Card className="border-[#294765] bg-[#0d223d]"><CardContent className="space-y-3 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-sm font-medium"><Search className="h-4 w-4 text-[#f0a35b]" />Buscar parámetros</div><p className="mt-1 text-[11px] text-[#9eb6ce]">Filtra rápidamente la biblioteca de parámetros disponibles del runtime.</p></div><Badge className="border border-[#6ea8ff]/30 bg-[#6ea8ff]/10 text-[#b8d5ff]">{visibleParameters.length} visibles</Badge></div><div className="relative"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-[#7893af]" /><Input value={parameterSearch} onChange={(event) => setParameterSearch(event.target.value)} placeholder="Buscar por nombre, clave, unidad o descripción…" className="border-[#557da5] bg-[#081a30] pl-9 text-xs text-[#edf4ff]" /></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{visibleParameters.map((parameter) => <button key={parameter.key} type="button" title={parameter.description} onClick={() => { if (parameter.key === "kind") setGeometry((current) => ({ ...current, kind: current.kind === "RECTANGULAR_MASS" ? "COURTYARD_MASS" : "RECTANGULAR_MASS" })); else setGeometry((current) => ({ ...current, [parameter.key]: current[parameter.key] })); }} className="rounded-lg border border-[#294765] bg-[#081a30] p-3 text-left transition-colors hover:border-[#f0a35b]"><span className="block text-xs font-medium text-[#edf4ff]">{parameter.label}</span><span className="mt-1 block font-mono text-[10px] text-[#f6c995]">{parameter.key} · {parameter.unit}</span><span className="mt-1 block text-[10px] leading-4 text-[#7893af]">{parameter.description}</span></button>)}{visibleParameters.length === 0 && <p className="text-xs text-[#f6c995]">No hay parámetros que coincidan con la búsqueda.</p>}</div></CardContent></Card><Card className="border-[#294765] bg-[#0d223d]"><CardContent className="flex flex-wrap items-center gap-3 p-4 text-xs text-[#b8cbe0]"><span className="uppercase tracking-[0.14em] text-[#7893af]">Hosts de ejecución</span>{hostWorkers.data?.map((worker) => <span key={worker.kind} className={worker.status === "READY" ? "rounded-full border border-emerald-400/30 px-2.5 py-1 text-emerald-200" : "rounded-full border border-amber-400/30 px-2.5 py-1 text-amber-200"}>{worker.kind.replace("_", " ")} · {worker.status}</span>)}<span className="text-[#7893af]">.rvt y .gh nativos se generan sólo mediante hosts autorizados.</span></CardContent></Card>
    <Card className="border-[#294765] bg-[#0d223d]"><CardContent className="space-y-3 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-sm font-medium"><GitCompare className="h-4 w-4 text-[#f0a35b]" />Comandos esenciales SICL/ARKI</div><p className="mt-1 text-[11px] text-[#9eb6ce]">Subconjunto del catálogo canónico compartido. No se crea un motor paralelo ni se renombra la semántica.</p></div><Badge className="border border-[#6ea8ff]/30 bg-[#6ea8ff]/10 text-[#b8d5ff]">{showAllCommands ? "67 comandos" : `${runtimeCommands.length} esenciales`}</Badge><button type="button" onClick={() => setShowAllCommands((value) => !value)} className="rounded border border-[#557da5] px-2 py-1 text-[10px] text-[#b8cbe0]">{showAllCommands ? "Ver esenciales" : "Ver todos"}</button></div><div className="flex flex-wrap items-center gap-2 text-[10px] text-[#9eb6ce]"><span className="uppercase tracking-[0.14em] text-[#f0a35b]">Atajos rápidos</span><span title="Escribe uno de estos atajos para obtener una previsualización canónica">/gen · /site · /status · /review · /decide</span></div><div className="grid gap-2 md:grid-cols-[1fr_auto] md:items-center"><div className="flex gap-2"><Input value={commandInput} onChange={(event) => { setCommandInput(event.target.value); setCommandResolution(null); }} onKeyDown={(event) => { if (event.key === "Enter") previewCommand(); }} placeholder="Escribe /gen, /site, /status o un comando canónico…" className="h-9 border-[#557da5] bg-[#081a30] font-mono text-xs text-[#edf4ff] placeholder:text-[#7893af]" /><Button size="sm" className="bg-[#6ea8ff] text-[#071a30]" onClick={() => previewCommand()}>Previsualizar</Button></div><div className="flex gap-1">{(["EXPLORE", "APPLY", "DECIDE"] as const).map((mode) => <button key={mode} type="button" title={mode === "EXPLORE" ? "Explorar sin modificar Project State" : mode === "APPLY" ? "Preparar un cambio con confirmación" : "Decidir solo con autoridad humana"} onClick={() => setRuntimeMode(mode)} className={runtimeMode === mode ? "rounded border border-[#f0a35b] bg-[#49351f] px-2 py-1 text-[9px] text-[#f6c995]" : "rounded border border-[#557da5] px-2 py-1 text-[9px] text-[#9eb6ce]"}>{mode}</button>)}</div></div>{commandInput.trim() && !commandResolution && <div className="flex flex-wrap gap-1">{shortcutSuggestions(commandInput).map((item) => <button key={item.shortcut} type="button" title={`Atajo ${item.shortcut}: ${item.description} → ${item.canonical}`} aria-label={`Usar ${item.shortcut} para ${item.canonical}`} onClick={() => { setCommandInput(item.shortcut); previewCommand(item.shortcut); }} className="rounded border border-[#294765] bg-[#081a30] px-2 py-1 text-[10px] text-[#b8cbe0] hover:border-[#f0a35b]">{item.shortcut} → {item.canonical}</button>)}</div>}{commandResolution && <div className={commandResolution.resolutionType === "UNKNOWN" || commandResolution.resolutionType === "AMBIGUOUS" ? "rounded border border-amber-400/40 bg-amber-400/10 p-3 text-[10px] text-amber-100" : "rounded border border-emerald-400/30 bg-emerald-400/10 p-3 text-[10px] text-emerald-100"}><div className="flex flex-wrap justify-between gap-2"><span>{commandResolution.resolutionType} · {runtimeMode}</span><span>{commandResolution.validationStatus}</span></div><p className="mt-1 font-mono">{commandResolution.resolvedCanonical ?? commandResolution.note}</p><p className="mt-1 text-[#b8cbe0]">{commandResolution.note} {runtimeMode === "EXPLORE" ? "No modifica Project State." : runtimeMode === "APPLY" ? "Requiere confirmación explícita antes de persistir." : "Requiere Human Authority; no se ejecuta desde esta vista."}</p></div>}<div className="flex flex-wrap gap-2">{visibleRuntimeCommands.map((command) => <button key={command.name} type="button" title={`Comando canónico ${command.name}. Seleccionar para ver su sintaxis.`} aria-label={`Seleccionar ${command.name}`} onClick={() => setSelectedRuntimeCommand(command.name)} className={selectedRuntimeCommand === command.name ? "rounded-full border border-[#f0a35b] bg-[#49351f] px-3 py-1.5 font-mono text-[10px] text-[#f6c995]" : "rounded-full border border-[#557da5] bg-[#081a30] px-3 py-1.5 font-mono text-[10px] text-[#b8cbe0] hover:border-[#f0a35b]"}>{command.name}</button>)}</div><div className="grid gap-3 md:grid-cols-[1fr_auto] md:items-center"><div className="rounded-lg border border-[#557da5] bg-[#081a30] p-3"><p className="font-mono text-xs text-[#f6c995]">{activeRuntimeCommand?.name}</p><p className="mt-1 font-mono text-[10px] text-[#9eb6ce]">{activeRuntimeCommand?.syntax}</p></div><div className="text-right text-[10px] text-[#7893af]">Contexto: <span className="font-mono text-[#b8d5ff]">{projectId}</span><br />Artefacto: <span className="font-mono text-[#b8d5ff]">{arkSummary?.name ?? proposalName + ".ark"}</span></div></div><p className="text-[10px] leading-4 text-[#7893af]">/DECISION RECORD y /ALTERNATIVE PROMOTE requieren Human Authority y no se ejecutan automáticamente desde este laboratorio.</p></CardContent></Card>
    <Card className="border-[#294765] bg-[#0d223d]"><CardContent className="space-y-3 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2 text-sm font-medium"><BookOpen className="h-4 w-4 text-[#f0a35b]" />Biblioteca de ejemplos repetibles</div><p className="mt-1 text-[11px] text-[#9eb6ce]">Un ejemplo por comando del catálogo canónico. Son materiales de aprendizaje: no ejecutan automáticamente Core, hosts profesionales ni decisiones humanas.</p></div><Badge className="border border-[#6ea8ff]/30 bg-[#6ea8ff]/10 text-[#b8d5ff]">{parametricExamples.length} comandos</Badge></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{parametricExamples.slice(0, 12).map((example) => <button key={example.exampleId} type="button" title={example.expectedOutcome} onClick={() => { setCommandInput(example.command); setCommandResolution(null); setTutorialStep(Math.max(tutorialStep, 1)); }} className="rounded-lg border border-[#294765] bg-[#081a30] p-3 text-left transition-colors hover:border-[#f0a35b]"><span className="block font-mono text-[10px] text-[#f6c995]">{example.exampleId}</span><span className="mt-1 block text-xs font-medium text-[#edf4ff]">{example.commandName}</span><span className="mt-1 block text-[10px] leading-4 text-[#7893af]">{example.learningObjective}</span><span className="mt-2 block text-[9px] uppercase tracking-[0.12em] text-[#9eb6ce]">{example.mode} · {example.artifacts.length ? "ARK/DYN/GHX" : "JSON"}</span></button>)}</div><p className="text-[10px] text-[#7893af]">Mostrando los primeros 12 para no saturar la vista. El manifiesto completo conserva los 67 ejemplos en la base de contenido.</p></CardContent></Card>
    <Card className="border-[#f0a35b]/40 bg-[#102947]"><CardContent className="flex flex-wrap items-center gap-3 p-3"><div className="flex min-w-[240px] flex-1 items-center gap-2"><span className="text-[#f0a35b]">✦</span><Input ref={commandInputRef} value={commandInput} onChange={(event) => { setCommandInput(event.target.value); setCommandResolution(null); }} onKeyDown={(event) => { if (event.key === "Enter") previewCommand(); }} placeholder="Pregunta a ARKI o escribe /comando…" className="border-[#557da5] bg-[#081a30] font-mono text-xs text-[#edf4ff] placeholder:text-[#7893af]" /><Button size="sm" onClick={() => previewCommand()} className="bg-[#f0a35b] text-black hover:bg-[#f6c995]">Enviar</Button></div><span className="rounded border border-[#557da5] px-2 py-1 font-mono text-[10px] text-[#b8cbe0]" title="Atajo para enfocar la barra de comandos">Ctrl+Y</span><span className="text-[10px] text-[#7893af]">Usa lenguaje natural, shortcuts o comandos canónicos.</span></CardContent></Card><div className="grid gap-5 xl:grid-cols-[250px_minmax(0,1fr)_320px]"><aside className="space-y-4"><Card className="border-[#294765] bg-[#0d223d]"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><GraduationCap className="h-4 w-4 text-[#f0a35b]" />Tutorial guiado</CardTitle><Progress value={((tutorialStep + 1) / tutorial.length) * 100} className="mt-3 h-2" /></CardHeader><CardContent className="space-y-3">{tutorial.map((item, index) => <button key={item.title} type="button" onClick={() => setTutorialStep(index)} className={`w-full rounded-lg border p-3 text-left ${tutorialStep === index ? "border-[#f0a35b] bg-[#17395c]" : "border-transparent bg-[#081a30]"}`}><div className="flex items-center gap-2"><span className="font-mono text-[10px] text-[#f0a35b]">0{index + 1}</span><span className="text-xs font-medium text-[#edf4ff]">{item.title}</span></div><p className="mt-2 text-[11px] leading-5 text-[#9eb6ce]">{item.detail}</p></button>)}<div className="rounded-lg border border-[#557da5] bg-[#081a30] p-3 text-[11px] leading-5 text-[#f6c995]"><strong>Ahora:</strong> {tutorial[tutorialStep].action}</div></CardContent></Card><Card className="border-[#294765] bg-[#0d223d]"><CardContent className="p-4 text-xs leading-5 text-[#9eb6ce]"><p className="font-medium text-[#edf4ff]">Contrato de aprendizaje</p><p className="mt-1">Modificar parámetros no equivale a diseñar. La simulación ayuda a observar consecuencias; el proceso arquitectónico todavía debe evaluar función, evidencia y autoridad humana.</p></CardContent></Card></aside>
      <section className="space-y-4"><Card className="border-[#557da5] bg-[#102947]"><CardHeader><div className="flex flex-wrap items-center justify-between gap-3"><div><Badge className="border border-[#6ea8ff]/30 bg-[#6ea8ff]/10 text-[#b8d5ff]">LIVE SVG PREVIEW</Badge><CardTitle className="mt-3 text-xl">{proposalName}.ark · {geometry.kind}</CardTitle></div><div className="flex gap-2"><Button variant="outline" size="sm" className="border-[#557da5] text-[#d7e5f4]" onClick={() => setCompareMode((value) => !value)}><GitCompare className="mr-2 h-4 w-4" />{compareMode ? "Cerrar comparación" : "Comparar variación"}</Button><Button onClick={() => setTutorialStep(Math.min(tutorialStep + 1, tutorial.length - 1))} className="bg-[#6ea8ff] text-[#071a30]"><Play className="mr-2 h-4 w-4" />Avanzar tutorial</Button></div></div></CardHeader><CardContent>{compareMode ? <div className="space-y-3"><div className="grid gap-4 lg:grid-cols-2"><div className="rounded-xl border border-[#f0a35b]/50 bg-[#0d223d] p-3"><div className="mb-2 flex items-center justify-between"><span className="text-xs font-semibold text-[#f6c995]">A · Actual</span><span className="font-mono text-[10px] text-[#7893af]">{geometry.width} × {geometry.depth} m</span></div><GeometryPreview geometry={geometry} animating={geometryAnimating} /></div><div className="rounded-xl border border-[#6ea8ff]/50 bg-[#0d223d] p-3"><div className="mb-2 flex items-center justify-between"><span className="text-xs font-semibold text-[#b8d5ff]">B · Variación</span><span className="font-mono text-[10px] text-[#7893af]">{comparisonGeometry.width} × {comparisonGeometry.depth} m</span></div><GeometryPreview geometry={comparisonGeometry} /></div></div><p className="text-xs text-[#9eb6ce]">La comparación es lado a lado y no selecciona una ganadora. Ambas variaciones deben pasar los mismos gates funcionales, normativos y de revisión humana.</p></div> : <GeometryPreview geometry={geometry} animating={geometryAnimating} />}<div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[#294765] bg-[#071a30] p-4"><div className="flex items-center gap-2 text-xs text-[#b8cbe0]"><CheckCircle2 className="h-4 w-4 text-emerald-300" />{geometryAnimating ? "Actualizando geometría…" : "Actualización determinista local · sin render diferido"}</div><div className="flex flex-wrap gap-2"><Button size="sm" onClick={exportAll} disabled={exportPackage.isPending} className="bg-[#f0a35b] text-[#081a30] hover:bg-[#f6c995]"><Download className="mr-1.5 h-3.5 w-3.5" />Exportar .ark + .dyn + .ghx</Button><Button size="sm" variant="outline" className="border-[#557da5] text-[#d7e5f4]" onClick={() => download(`${proposalName}.json`, JSON.stringify(previewResult, null, 2), "application/json")}><FileJson className="mr-1.5 h-3.5 w-3.5" />JSON</Button></div></div></CardContent></Card><Card className="border-[#294765] bg-[#0d223d]"><CardHeader><CardTitle className="flex items-center gap-2 text-lg"><BookOpen className="h-4 w-4 text-[#f0a35b]" />Ejercicio evaluable</CardTitle></CardHeader><CardContent className="space-y-4"><p className="text-sm text-[#d7e5f4]">{quiz.question}</p><div className="grid gap-2">{quiz.options.map((option, index) => <button key={option} type="button" onClick={() => setQuizAnswer(index)} className={`rounded-lg border p-3 text-left text-xs ${quizAnswer === index ? "border-[#f0a35b] bg-[#49351f] text-[#f6c995]" : "border-[#294765] bg-[#081a30] text-[#b8cbe0]"}`}>{option}</button>)}</div><div className="flex items-center gap-3"><Button onClick={submitQuiz} disabled={quizAnswer === null} className="bg-[#6ea8ff] text-[#071a30]">Evaluar respuesta</Button>{quizScore !== null && <Badge className={quizScore === 100 ? "border-emerald-400/30 bg-emerald-400/10 text-emerald-200" : "border-rose-400/30 bg-rose-400/10 text-rose-200"}>Resultado: {quizScore}/100</Badge>}</div></CardContent></Card></section>
      <aside className="space-y-4"><Card className="border-[#294765] bg-[#0d223d]"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><SlidersIcon />Parámetros en vivo</CardTitle></CardHeader><CardContent className="space-y-4">{[["width", "Ancho", 8, 60, 1], ["depth", "Fondo", 8, 50, 1], ["height", "Altura por nivel", 2.4, 8, 0.1], ["floors", "Niveles", 1, 12, 1], ["courtyardRatio", "Patio relativo", 0, 0.6, 0.05]].map(([key, label, min, max, step]) => <div key={String(key)}><div className="flex justify-between text-xs"><label htmlFor={`geo-${key}`}>{label}</label><span className="font-mono text-[#f6c995]">{Number(geometry[key as keyof Geometry]).toFixed(key === "height" || key === "courtyardRatio" ? 1 : 0)}</span></div><input id={`geo-${key}`} type="range" min={String(min)} max={String(max)} step={String(step)} value={Number(geometry[key as keyof Geometry])} onChange={(event) => setNumber(key as keyof Geometry, event.target.value)} className="mt-2 w-full accent-[#f0a35b]" /></div>)}<Separator className="bg-[#294765]" /><p className="text-[11px] leading-5 text-[#7893af]">Los valores modifican inmediatamente la planta, la axonometría y el paquete exportable.</p></CardContent></Card>{compareMode && <Card className="border-[#6ea8ff]/50 bg-[#0d223d]"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><GitCompare className="h-4 w-4 text-[#b8d5ff]" />Variación B</CardTitle></CardHeader><CardContent className="space-y-4">{[["width", "Ancho", 8, 60, 1], ["depth", "Fondo", 8, 50, 1], ["height", "Altura por nivel", 2.4, 8, 0.1], ["floors", "Niveles", 1, 12, 1], ["courtyardRatio", "Patio relativo", 0, 0.6, 0.05]].map(([key, label, min, max, step]) => <div key={"compare-" + String(key)}><div className="flex justify-between text-xs"><label htmlFor={"compare-" + String(key)}>{label}</label><span className="font-mono text-[#b8d5ff]">{Number(comparisonGeometry[key as keyof Geometry]).toFixed(key === "height" || key === "courtyardRatio" ? 1 : 0)}</span></div><input id={"compare-" + String(key)} type="range" min={String(min)} max={String(max)} step={String(step)} value={Number(comparisonGeometry[key as keyof Geometry])} onChange={(event) => setComparisonNumber(key as keyof Geometry, event.target.value)} className="mt-2 w-full accent-[#6ea8ff]" /></div>)}</CardContent></Card>}<Card className="border-[#294765] bg-[#0d223d]"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><FileCode2 className="h-4 w-4 text-[#f0a35b]" />Destinos de intercambio</CardTitle></CardHeader><CardContent className="space-y-3 text-xs text-[#b8cbe0]"><div className="rounded-lg border border-emerald-400/30 bg-emerald-400/10 p-3"><strong className="text-emerald-200">.dyn · Dynamo/Revit</strong><p className="mt-1 text-[#9eb6ce]">Se genera el grafo de intercambio; la ejecución requiere Dynamo/Revit autorizado.</p></div><div className="rounded-lg border border-emerald-400/30 bg-emerald-400/10 p-3"><strong className="text-emerald-200">.ghx · Grasshopper/Rhino</strong><p className="mt-1 text-[#9eb6ce]">Se genera XML legible; la ejecución requiere Rhino/Grasshopper o Rhino.Compute.</p></div><div className="rounded-lg border border-amber-400/30 bg-amber-400/10 p-3"><strong className="text-amber-200">.rvt · .gh nativos</strong><p className="mt-1 text-[#9eb6ce]">No se fabrican binarios nativos. Se activarán mediante host externo, token, versión y revisión humana.</p></div></CardContent></Card></aside></div></div></main>;
}

function SlidersIcon() { return <span className="inline-block h-4 w-4 rounded border border-[#f0a35b]" aria-hidden="true" />; }
